    "title": "โค้ดตัวอย่างคำนวณ BPM (Beats Per Minute)",
    "code": "// Heartbeat BPM Calculation\n// AO -> A0\n\n#define HEARTBEAT_PIN A0\n#define LED_PIN 13\n\nunsigned long lastBeatTime = 0;\nint bpm = 0;\nbool pulseDetected = false;\n\nvoid setup() {\n  Serial.begin(9600);\n  pinMode(LED_PIN, OUTPUT);\n  Serial.println(\"Heartbeat BPM Monitor\");\n}\n\nvoid loop() {\n  int rawValue = analogRead(HEARTBEAT_PIN);\n  \n  // หาจุดสูงสุด (Peak detection)\n  if (rawValue > 600 && !pulseDetected) {\n    pulseDetected = true;\n    \n    unsigned long currentTime = millis();\n    unsigned long beatInterval = currentTime - lastBeatTime;\n    lastBeatTime = currentTime;\n    \n    // คำนวณ BPM\n    if (beatInterval > 0) {\n      bpm = 60000 / beatInterval;\n      \n      if (bpm > 40 && bpm < 200) {  // กรองค่าที่ไม่สมจริง\n        Serial.print(\"❤️  BPM: \");\n        Serial.println(bpm);\n        digitalWrite(LED_PIN, HIGH);\n      }\n    }\n  }\n  \n  if (rawValue < 550) {\n    pulseDetected = false;\n    digitalWrite(LED_PIN, LOW);\n  }\n  \n  delay(20);\n}\n"
